import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"升级与数据迁移","description":"","frontmatter":{},"headers":[],"relativePath":"operations/upgrade.md","filePath":"operations/upgrade.md","lastUpdated":1788625494000}`),a={name:`operations/upgrade.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="升级与数据迁移" tabindex="-1">升级与数据迁移 <a class="header-anchor" href="#升级与数据迁移" aria-label="Permalink to “升级与数据迁移”">​</a></h1><p>升级要同时保护业务数据、密钥、配置和可回退能力。当前版本迁移序列为 <code>001</code>–<code>065</code>，后端启动时自动执行未完成项。</p><h2 id="升级前" tabindex="-1">升级前 <a class="header-anchor" href="#升级前" aria-label="Permalink to “升级前”">​</a></h2><ol><li>固定并审查准备部署的 Git 提交，不在生产机自动拉取未知变更。</li><li>记录当前提交、镜像摘要、容器状态、迁移版本和关键数据计数。</li><li>备份 PostgreSQL、邮件存储、上传目录、<code>.env</code>、KEK 和 TLS 配置。</li><li>验证备份可以读取，并在隔离数据库恢复一次。</li><li>在恢复副本执行全部迁移、后端测试和核心业务写操作。</li><li>安排维护窗口，暂停会造成数据持续变化的入口。</li></ol><p>数据库示例中的服务名、用户和库名按部署修改：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">db-use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">db-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> database.dump</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> database.dump</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>只有成功做过恢复演练的文件才算可用备份。</p><h2 id="_050–065-迁移内容" tabindex="-1">050–065 迁移内容 <a class="header-anchor" href="#_050–065-迁移内容" aria-label="Permalink to “050–065 迁移内容”">​</a></h2><table tabindex="0"><thead><tr><th>迁移</th><th>作用</th></tr></thead><tbody><tr><td>050</td><td>保证同一 OAuth 提供方身份只能创建一个独立用户</td></tr><tr><td>051</td><td>在用户表持久化令牌撤销边界，避免 Redis 丢失后旧会话复活</td></tr><tr><td>052</td><td>为出站通道小时/每日额度增加幂等预留</td></tr><tr><td>053</td><td>删除没有运行时约束的旧“已验证邮箱数量”设置</td></tr><tr><td>054</td><td>按收件人数原子记录用户每日发信用量和能量预留</td></tr><tr><td>055</td><td>扩大个人图床加密密钥字段，容纳完整密文</td></tr><tr><td>056</td><td>为个人与组织存储额度增加短期预留</td></tr><tr><td>057</td><td>删除用户时保留必要审计日志</td></tr><tr><td>058</td><td>强制订单、订阅只能有一个明确的计费所有者</td></tr><tr><td>059</td><td>为短窗口 SMTP 重试增加入站邮件指纹去重</td></tr><tr><td>060</td><td>把邮箱共享约束为只读权限</td></tr><tr><td>061</td><td>每个全局或邮箱范围只允许一个默认签名</td></tr><tr><td>062</td><td>规范化 OAuth 身份键，并阻止大小写、空白或跨表归属冲突</td></tr><tr><td>063</td><td>规范化已验证找回邮箱，并保证一个地址只归一个用户</td></tr><tr><td>064</td><td>把拦截记录升级为保存完整原文、认证结果、指纹和处理状态的持久隔离区</td></tr><tr><td>065</td><td>建立组织每日收件人数用量与预留账本，把企业邮箱历史当日用量从成员个人账本迁出</td></tr></tbody></table><p>050、058、062 和 063 遇到歧义数据会主动停止，不会猜测归属。升级前应在副本检查重复 OAuth 身份、双所有者订单/订阅、空身份键、跨表冲突和重复已验证找回邮箱。</p><p>064 不会为升级前的拦截记录虚构正文；这些行会标记为不可放行的历史记录。065 会迁移仍存在的企业发信预留，并根据 054 的应用时间重建当日早期企业发送用量，再从成员个人账本扣除同一批企业流量。升级副本中应核对组织总数、当日企业收件人数、个人用量变化和预留状态，不能只确认表已创建。</p><h2 id="执行升级" tabindex="-1">执行升级 <a class="header-anchor" href="#执行升级" aria-label="Permalink to “执行升级”">​</a></h2><p>在审查过的工作树中：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prune</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">reviewed-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=300</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>部署脚本只使用当前工作树，不自动执行 <code>git pull</code>。先构建镜像，再在维护窗口让单个后端实例执行迁移；确认后端健康和迁移版本后再恢复全部入口。</p><h2 id="数据核对" tabindex="-1">数据核对 <a class="header-anchor" href="#数据核对" aria-label="Permalink to “数据核对”">​</a></h2><p>升级前后至少比较：</p><ul><li>用户、邮箱、邮件、附件和组织数量。</li><li>OAuth 绑定唯一性及 NodeLoc 等级字段。</li><li>邮箱和邮件是否存在孤立外键。</li><li>IMAP UID 是否在邮箱内唯一。</li><li>订单与订阅是否只有一个所有者。</li><li>邮箱共享是否全部为只读。</li><li>默认签名是否在每个范围唯一。</li><li>迁移记录是否完整到 <code>065</code>。</li><li>隔离原文大小是否计入个人或组织存储，升级前历史记录是否保持“不可放行”。</li><li>当日企业发信是否只计组织账本，成员个人账本是否已移除同一企业流量。</li></ul><p>数据量会因维护窗口内合法业务变化而不同。比较时记录时间边界，不只追求数字完全相等。</p><h2 id="功能验证" tabindex="-1">功能验证 <a class="header-anchor" href="#功能验证" aria-label="Permalink to “功能验证”">​</a></h2><ul><li>官网、<code>/app/</code>、登录、注册和管理员入口。</li><li>已有账号不进入重复引导；管理员直接进入后台。</li><li>普通账号、NodeLoc 账号、NodeLoc 真实等级和系统配额徽章正确。</li><li>注册验证码、找回密码、找回邮箱绑定、Turnstile 与 OAuth。</li><li>邮箱创建、收信、业务发信、草稿、搜索、附件、导入导出和邮箱级转发。</li><li>高风险隔离、净化预览、放行到收件箱、永久删除与清理统计。</li><li>共享只读、转让并发、清理取消、个人邮箱永久清理，以及个人清理不能处理企业邮箱。</li><li>组织、域名、成员、仅对处于生效或宽限状态的组织与企业套餐开放的已验证域名品牌、企业邮箱、套餐和全组织共享每日发信额度。</li><li>支付回调幂等、订单、钱包、兑换码和订阅。</li><li>SMTP、IMAPS、POP3S、Redis、rspamd、Nginx 与 DNS/TLS。</li></ul><p>真实付款、外部批量发信和永久删除优先在隔离环境完成。生产只用明确标记的测试对象，并立即清理。</p><h2 id="回退" tabindex="-1">回退 <a class="header-anchor" href="#回退" aria-label="Permalink to “回退”">​</a></h2><p>先判断已经执行的新迁移是否与旧代码兼容。若不兼容，停止所有写入，从升级前备份整体恢复数据库、邮件数据、配置和对应代码。不要只回退镜像却保留旧程序无法理解的新约束。</p><p>回退后重新核对数据、协议端口、证书和外部回调，并记录失败原因。修复后重新走副本迁移和完整验证。</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};